svg.script:
// setClock(hh, mm, MM, DD)：游戏可直接复用这个函数，按游玩时间调用。
// 下面的自动走时只用于单独打开本 SVG 预览：从 10/17 23:54 开始按真实时间走，冒号每秒闪烁。
var SEG = {0:'abcdef',1:'bc',2:'abged',3:'abgcd',4:'fgbc',5:'afgcd',6:'afgedc',7:'abc',8:'abcdefg',9:'abcdfg'};
function setDigit(prefix, n) {
  'abcdefg'.split('').forEach(function (s) {
    var el = document.getElementById(prefix + '-' + s);
    if (el) el.style.display = SEG[n].indexOf(s) >= 0 ? '' : 'none';
  });
}
function setClock(hh, mm, MM, DD) {
  var t = String(hh).padStart(2, '0') + String(mm).padStart(2, '0');
  var d = String(MM).padStart(2, '0') + String(DD).padStart(2, '0');
  for (var i = 0; i < 4; i++) { setDigit('clk-' + i, +t[i]); setDigit('date-' + i, +d[i]); }
}
(function () {
  var start = Date.now(), base = 23 * 60 + 54;
  function tick() {
    var sec = Math.floor((Date.now() - start) / 1000);
    var m = base + Math.floor(sec / 60), day = 17 + Math.floor(m / 1440); m %= 1440;
    setClock(Math.floor(m / 60), m % 60, 10, day);
    var on = sec % 2 === 0 ? '' : 'none';
    document.getElementById('clk-colon-1').style.display = on;
    document.getElementById('clk-colon-2').style.display = on;
  }
  tick(); setInterval(tick, 500);
})();
